"""Diagnostic registry, aliases, and ordered reporting policy.

Spec: docs/specs/02-backstitch-core.md [SC-6], [SC-11], [SC-15]
Spec: docs/specs/03-backstitch-configuration.md [CFG-5], [CFG-6], [CFG-8]
Spec: docs/specs/04-backstitch-traceability-exclusions.md [EXC-4], [EXC-8]
Spec: docs/specs/05-backstitch-invariants.md [INV-4], [INV-8]
"""

from __future__ import annotations

import dataclasses
import functools
import importlib.resources
import tomllib
from dataclasses import dataclass
from typing import Any, Literal

Severity = Literal["error", "warning", "info"]
DiagnosticLevel = Literal["error", "warning", "info", "off"]
DiagnosticStatus = Literal["implemented", "reserved", "deprecated", "redirected"]

SEVERITIES: frozenset[str] = frozenset({"error", "warning", "info"})
DIAGNOSTIC_LEVELS: frozenset[str] = frozenset({"error", "warning", "info", "off"})
DIAGNOSTIC_STATUSES: frozenset[str] = frozenset(
    {"implemented", "reserved", "deprecated", "redirected"}
)
DEFAULTS_RESOURCE = "defaults.toml"
OFF_AUDIT_REASON = "diagnostic level off"
SEMANTIC_DIAGNOSTIC_PREFIX = "SEMANTIC_"


class DiagnosticConfigError(ValueError):
    """The packaged diagnostic registry or configured policy is invalid."""


@dataclass(frozen=True, slots=True)
class DiagnosticDefinition:
    code: str
    short_code: str
    status: DiagnosticStatus
    summary: str
    contexts: tuple[str, ...] = ()
    replacement: str | None = None


@dataclass(frozen=True, slots=True)
class DiagnosticRegistry:
    definitions: dict[str, DiagnosticDefinition]
    short_to_code: dict[str, str]

    def require(self, code: str) -> DiagnosticDefinition:
        try:
            return self.definitions[code]
        except KeyError:
            raise DiagnosticConfigError(f"unknown diagnostic code: {code}") from None

    def canonical_code(self, code_or_short: str) -> str:
        if code_or_short in self.definitions:
            code = code_or_short
        elif code_or_short in self.short_to_code:
            code = self.short_to_code[code_or_short]
        else:
            raise DiagnosticConfigError(f"unknown diagnostic code: {code_or_short}")

        chain: list[str] = []
        seen: set[str] = set()
        while True:
            if code in seen:
                cycle = " -> ".join((*chain, code))
                raise DiagnosticConfigError(
                    f"diagnostic replacement cycle detected: {cycle}"
                )
            seen.add(code)
            chain.append(code)

            definition = self.require(code)
            if definition.status == "implemented":
                return code
            if definition.status not in {"deprecated", "redirected"}:
                raise DiagnosticConfigError(
                    f"diagnostic {code_or_short} resolves to {code} with status"
                    f" {definition.status}; expected implemented"
                )
            if definition.replacement is None:
                raise DiagnosticConfigError(
                    f"diagnostic {code} has status {definition.status} but no replacement"
                )
            if definition.replacement not in self.definitions:
                raise DiagnosticConfigError(
                    f"diagnostic {code} replacement is not a known diagnostic:"
                    f" {definition.replacement}"
                )
            code = definition.replacement

    def implemented_codes(self) -> frozenset[str]:
        return frozenset(
            code
            for code, definition in self.definitions.items()
            if definition.status == "implemented"
        )


@dataclass(frozen=True, slots=True)
class DiagnosticLevelRule:
    selectors: tuple[str, ...]
    level: DiagnosticLevel


@dataclass(frozen=True, slots=True)
class DiagnosticsSettings:
    default_level: DiagnosticLevel = "warning"
    levels: tuple[DiagnosticLevelRule, ...] = ()
    fail_on: tuple[Severity, ...] = ("error",)
    suppressible_levels: tuple[Severity, ...] = ("warning", "info")


@functools.cache
def load_default_config_raw() -> dict[str, Any]:
    """Return Backstitch's packaged default TOML body."""

def validate_lint_codes(
    lint: LintSettings, *, allow_unknown: bool
) -> list[SuppressionDiagnostic]:
    """Validate suppression codes in config lint tables ([EXC-4]).

    Raises ``UnknownSuppressionCodeError`` by default; ``allow_unknown``
    downgrades unknown codes to returned warnings. Shared by the check
    pipeline and `config show` so both apply the same load strictness.
    """

    diagnostics: list[SuppressionDiagnostic] = []
    for table_name, table in (
        ("lint.per-file-ignores", lint.per_file_ignores),
        ("lint.per-section-ignores", lint.per_section_ignores),
    ):
        for path_key, codes in table.items():
            for code in codes:
                if not is_ordinary_diagnostic_code(code):
                    # [EXC-4]: unknown suppression codes fail load by
                    # default -- same hatch, same scope as [CFG-8].
                    message = (
                        f"unknown issue code `{code}` in {table_name} for {path_key}"
                    )
                    if not allow_unknown:
                        raise UnknownSuppressionCodeError(message)
                    diagnostics.append(
                        _suppression_diagnostic(
                            "SUPPRESSION_UNKNOWN_CODE",
                            message,
                            path=path_key,
                            line=None,
                        )
                    )
    return diagnostics

def _pyproject_has_backstitch(path: Path) -> bool:
    try:
        data = tomllib.loads(path.read_text(encoding="utf-8"))
    except tomllib.TOMLDecodeError as exc:
        # [CFG-8]: a pyproject.toml that does not parse cannot be checked
        # for a [tool.backstitch] table -- exit 2 naming the file, never a
        # silent skip to the next ancestor.
        msg = f"Invalid TOML in {path} during config discovery: {exc}"
        raise ConfigLoadError(msg) from exc
    return "backstitch" in data.get("tool", {})

def _unknown_key_messages(raw: dict[str, Any], config_path: Path) -> list[str]:
    """[CFG-8] unknown-key inventory, each message naming key and file."""

    messages: list[str] = []
    for key, value in raw.items():
        if key in _TABLE_KEYS:
            if isinstance(value, dict):
                allowed = _table_key_names(key)
                if key == "diagnostics" and _is_packaged_default_path(config_path):
                    allowed = allowed | frozenset({"registry"})
                messages.extend(
                    f"unknown config key `{key}.{sub}` in {config_path}"
                    for sub in _unused_table_keys(value, allowed)
                )
                if key == "analyze":
                    evaluation = value.get("eval")
                    if isinstance(evaluation, dict):
                        messages.extend(
                            f"unknown config key `analyze.eval.{sub}` in {config_path}"
                            for sub in _unused_table_keys(
                                evaluation, _ANALYZE_EVAL_KEYS
                            )
                        )
                    dispositions = value.get("dispositions")
                    if isinstance(dispositions, list):
                        for index, disposition in enumerate(dispositions):
                            messages.extend(
                                "unknown config key "
                                f"`analyze.dispositions[{index}].{sub}` in {config_path}"
                                for sub in _unused_table_keys(
                                    disposition, _DISPOSITION_KEYS
                                )
                            )
                if key == "diagnostics":
                    rules = value.get("levels")
                    if isinstance(rules, list):
                        for index, rule in enumerate(rules):
                            messages.extend(
                                "unknown config key "
                                f"`diagnostics.levels[{index}].{sub}` in {config_path}"
                                for sub in _unused_table_keys(
                                    rule, frozenset({"select", "level"})
                                )
                            )
            continue
        if key in _TOP_LEVEL_KEYS:
            continue
        messages.append(f"unknown config key `{key}` in {config_path}")
    return messages
